    "viewBox": "0 0 560 340",
    "svg": "<rect class=\"plate\" x=\"0\" y=\"0\" width=\"560\" height=\"340\" rx=\"12\"/><rect class=\"panel\" rx=\"9\" x=\"14\" y=\"14\" width=\"258\" height=\"312\"/><rect class=\"panelHead\" rx=\"9\" x=\"14\" y=\"14\" width=\"258\" height=\"26\"/><rect class=\"panelHead\" x=\"14\" y=\"31\" width=\"258\" height=\"9\"/><line class=\"rule\" x1=\"14\" y1=\"40\" x2=\"272\" y2=\"40\"/><text class=\"lblL\" x=\"24\" y=\"31.5\">A · two places</text><circle class=\"fillC\" stroke=\"currentColor\" stroke-width=\"2\" cx=\"77.48\" cy=\"141.08\" r=\"22\"/><text class=\"lblXS\" x=\"77.48\" y=\"147.63\" text-anchor=\"middle\">brain</text><rect class=\"fillB\" rx=\"7\" stroke=\"currentColor\" stroke-width=\"1.5\" x=\"161.72\" y=\"93.92\" width=\"79.56\" height=\"94.32\"/><text class=\"lblXS\" x=\"201.5\" y=\"147.63\" text-anchor=\"middle\">muscle</text><line class=\"ln\" x1=\"110.24\" y1=\"141.08\" x2=\"157.04\" y2=\"141.08\"/><path class=\"ln solid\" d=\"M157.04 141.08l-4 -2.48v4l4.96z\"/><text class=\"lblXS\" x=\"133.64\" y=\"116.19\" text-anchor=\"middle\">central</text><text class=\"lblXS\" x=\"35.36\" y=\"214.44\">less drive</text><text class=\"lblXS\" x=\"35.36\" y=\"244.57\">more effort felt</text><text class=\"lblXS\" x=\"35.36\" y=\"274.7\">motivation ↓</text><text class=\"lblXS\" x=\"161.72\" y=\"214.44\">by-products</text><text class=\"lblXS\" x=\"161.72\" y=\"244.57\">low glycogen</text><text class=\"lblXS\" x=\"161.72\" y=\"274.7\">salt + calcium</text><rect class=\"panel\" rx=\"9\" x=\"288\" y=\"14\" width=\"258\" height=\"312\"/><rect class=\"panelHead\" rx=\"9\" x=\"288\" y=\"14\" width=\"258\" height=\"26\"/><rect class=\"panelHead\" x=\"288\" y=\"31\" width=\"258\" height=\"9\"/><line class=\"rule\" x1=\"288\" y1=\"40\" x2=\"546\" y2=\"40\"/><text class=\"lblL\" x=\"298\" y=\"31.5\">B · they stack</text><line class=\"ax\" x1=\"300\" y1=\"314\" x2=\"534\" y2=\"314\"/><line class=\"ax\" x1=\"300\" y1=\"52\" x2=\"300\" y2=\"314\"/><line class=\"grid\" x1=\"378\" y1=\"52\" x2=\"378\" y2=\"314\"/><line class=\"grid\" x1=\"456\" y1=\"52\" x2=\"456\" y2=\"314\"/><line class=\"grid\" x1=\"300\" y1=\"139.333\" x2=\"534\" y2=\"139.333\"/><line class=\"grid\" x1=\"300\" y1=\"226.667\" x2=\"534\" y2=\"226.667\"/><path class=\"ln\" d=\"M300 93.92Q417 188.24 475.5 238.02L534 287.8\"/><path class=\"ln\" d=\"M300 93.92Q417 167.28 475.5 206.58L534 245.88\"/><text class=\"lblXS\" x=\"501.24\" y=\"298.28\" text-anchor=\"end\">output</text><text class=\"lblXS\" x=\"501.24\" y=\"256.36\" text-anchor=\"end\">central only</text><text class=\"lblXS\" x=\"417\" y=\"304.83\" text-anchor=\"middle\">time under load  →</text><rect class=\"fillA\" rx=\"6\" x=\"309.36\" y=\"130.6\" width=\"215.28\" height=\"25\"/><text class=\"lblXS\" x=\"317.55\" y=\"142.39\">treat the muscle and</text><text class=\"lblXS\" x=\"317.55\" y=\"155.39\">the head separately</text>",
